+import type { Board, Pos, Verdict } from "./types";
+
+export function horseMove(board: Board, from: Pos, to: Pos): Verdict {
+  const dx = Math.abs(to.x - from.x);
+  const dy = Math.abs(to.y - from.y);
+  if ((dx === 1 && dy === 2) || (dx === 2 && dy === 1)) return { legal: true };
+  return { legal: false, reason: "马走日" };
+}
